Nice direction — I took the liberty of translating the Python logic into PHP and sprinkled inline comments so the flow should be easy to follow. Take a glance and tell me if you'd like the comments more verbose, or converted into PHPDoc blocks.

```php
<?php
// Translate of the provided Python function `prod_signs` into PHP.
// - For each unique value in $arr whose absolute value is prime:
//     - if that exact value appears an even number of times in $arr, add it
//     - if it appears an odd number of times, subtract it
// - If there are no such primes, return null

function prod_signs(array $arr): ?int
{
    // helper closure to test whether a non-negative integer is prime
    $is_prime = function (int $n): bool {
        // numbers less than 2 are not prime
        if ($n < 2) {
            return false;
        }
        // only need to test divisors up to sqrt(n)
        $limit = (int) sqrt($n);
        for ($i = 2; $i <= $limit; $i++) {
            if ($n % $i === 0) {
                return false;
            }
        }
        return true;
    };

    // get unique values from the input array (preserve signs)
    $unique = array_values(array_unique($arr));

    // collect those unique values whose absolute value is prime
    $primes = [];
    foreach ($unique as $value) {
        // use abs() so -3 and 3 are both recognized by primality check
        if ($is_prime(abs((int) $value))) {
            $primes[] = $value; // keep original sign (could be negative)
        }
    }

    // if there are no prime candidates, mirror Python's `None` with PHP null
    if (empty($primes)) {
        return null;
    }

    // precompute how many times each exact value appears in the original array
    $counts = array_count_values($arr);

    // sum primes with sign determined by parity of their counts
    $sum = 0;
    foreach ($primes as $p) {
        // count occurrences of the exact value (signed)
        $count = $counts[$p] ?? 0;

        // if count is even, add the value; if odd, subtract it
        if ($count % 2 === 0) {
            $sum += $p;
        } else {
            $sum -= $p;
        }
    }

    return $sum;
}

// Example (uncomment to test):
// $arr = [3, 3, -3, 5, 5, 5];
// var_dump(prod_signs($arr));
