            return c;
    }
    return -1; // not found
}

wxString GetCellValueByColLabel(wxGrid* grid, int row, const wxString& colLabel)
{
    int col = FindColByLabel(grid, colLabel);
    if (col == -1) return wxEmptyString;
    return grid->GetCellValue(row, col);
}

