A small, flexible approach — quietly adaptable, open to interpretation. Below is a compact utility that answers "is this in the array?" but can also be asked to be forgiving about types (for example searching for "3" in an array of numbers).

Code (copy/paste):

```javascript
function findInArray(arr, target, {coerce = false} = {}) {
  function isEqual(a, b) {
    if (a === b) return true;            // strict fastest path
    if (!coerce) return false;           // no coercion requested
    // try numeric coercion when sensible
    const na = Number(a), nb = Number(b);
    if (!Number.isNaN(na) && !Number.isNaN(nb)) return na === nb;
    // fallback to abstract equality as a last resort
    return a == b;
  }

  const indices = [];
  arr.forEach((item, i) => { if (isEqual(item, target)) indices.push(i); });

  return {
    exists: indices.length > 0,
    indices,
    count: indices.length,
    matches: indices.map(i => arr[i])
  };
}

// Example usage with your data:
const arr = [1,2,3,4,5,5,4,3,2,1];
const search = "3";

console.log(findInArray(arr, search));                // strict (default) -> exists: false
console.log(findInArray(arr, search, {coerce:true})); // with coercion -> exists: true, indices: [2,7]
```

